"""Products API with an append-only audit log of before/after diffs.

Every *successful* mutating request (PUT / PATCH / DELETE) appends one row to
``audit_log``:

    {id, ts, actor, action, entity_id, diff}

where ``diff`` is a JSON object mapping each changed field to
``{"old": <previous value>, "new": <new value>}``.

Reads (GET) never log. Failed mutations (validation errors, unknown entity)
never log either.
"""

import json
import os
import sqlite3
from datetime import datetime, timezone

from flask import Flask, g, jsonify, request

DATABASE = os.environ.get("DB_PATH", os.path.join(os.path.dirname(__file__), "app.db"))

# Fields a client may set on a product.
PRODUCT_FIELDS = ("name", "price", "stock")

app = Flask(__name__)


# --------------------------------------------------------------------------
# Database helpers
# --------------------------------------------------------------------------

def get_db() -> sqlite3.Connection:
    if "db" not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db


@app.teardown_appcontext
def close_db(_exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


SCHEMA = """
CREATE TABLE IF NOT EXISTS products (
    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    name  TEXT NOT NULL,
    price REAL NOT NULL,
    stock INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS audit_log (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    ts        TEXT NOT NULL,
    actor     TEXT,
    action    TEXT NOT NULL,
    entity_id INTEGER NOT NULL,
    diff      TEXT NOT NULL
);
"""


def init_db(db_path: str | None = None) -> None:
    path = db_path or DATABASE
    conn = sqlite3.connect(path)
    try:
        conn.executescript(SCHEMA)
        conn.commit()
    finally:
        conn.close()


def row_to_dict(row: sqlite3.Row) -> dict:
    return {"id": row["id"], "name": row["name"], "price": row["price"], "stock": row["stock"]}


# --------------------------------------------------------------------------
# Audit helpers
# --------------------------------------------------------------------------

def current_actor() -> str | None:
    return request.headers.get("X-User-ID")


def write_audit(action: str, entity_id: int, diff: dict) -> None:
    """Append one audit_log row. Called only after a mutation succeeded."""
    get_db().execute(
        "INSERT INTO audit_log (ts, actor, action, entity_id, diff) VALUES (?, ?, ?, ?, ?)",
        (
            datetime.now(timezone.utc).isoformat(),
            current_actor(),
            action,
            entity_id,
            json.dumps(diff),
        ),
    )


def diff_fields(old: dict, new: dict) -> dict:
    """Return {field: {"old": x, "new": y}} for fields whose value changed."""
    return {
        f: {"old": old.get(f), "new": new[f]}
        for f in new
        if f in old and old.get(f) != new[f]
    }


# --------------------------------------------------------------------------
# Routes
# --------------------------------------------------------------------------

@app.post("/products")
def create_product():
    payload = request.get_json(silent=True) or {}
    if "name" not in payload or "price" not in payload:
        return jsonify(error="name and price are required"), 400

    name = payload["name"]
    price = payload["price"]
    stock = payload.get("stock", 0)
    if not isinstance(name, str) or not name.strip():
        return jsonify(error="name must be a non-empty string"), 400
    if not isinstance(price, (int, float)) or isinstance(price, bool) or price < 0:
        return jsonify(error="price must be a non-negative number"), 400
    if not isinstance(stock, int) or isinstance(stock, bool) or stock < 0:
        return jsonify(error="stock must be a non-negative integer"), 400

    db = get_db()
    cur = db.execute(
        "INSERT INTO products (name, price, stock) VALUES (?, ?, ?)",
        (name.strip(), float(price), stock),
    )
    entity_id = cur.lastrowid

    # Log creation so /history can rebuild the row starting from nothing.
    write_audit(
        "CREATE",
        entity_id,
        {"name": {"old": None, "new": name.strip()},
         "price": {"old": None, "new": float(price)},
         "stock": {"old": None, "new": stock}},
    )
    db.commit()

    row = db.execute("SELECT * FROM products WHERE id = ?", (entity_id,)).fetchone()
    return jsonify(row_to_dict(row)), 201


def _apply_update(entity_id: int, payload: dict, full_replace: bool):
    """Shared logic for PUT (full_replace=True) and PATCH."""
    db = get_db()
    row = db.execute("SELECT * FROM products WHERE id = ?", (entity_id,)).fetchone()
    if row is None:
        # Failed mutation: log nothing.
        return jsonify(error="product not found"), 404

    if not isinstance(payload, dict) or not payload:
        return jsonify(error="JSON object body required"), 400

    unknown = set(payload) - set(PRODUCT_FIELDS)
    if unknown:
        return jsonify(error=f"unknown fields: {sorted(unknown)}"), 400

    if full_replace:
        missing = set(PRODUCT_FIELDS) - set(payload)
        if missing:
            return jsonify(error=f"PUT requires all fields, missing: {sorted(missing)}"), 400

    # Validate provided values against the current row as the baseline.
    candidate = row_to_dict(row)
    for f in PRODUCT_FIELDS:
        if f not in payload:
            continue
        v = payload[f]
        if f == "name":
            if not isinstance(v, str) or not v.strip():
                return jsonify(error="name must be a non-empty string"), 400
            candidate[f] = v.strip()
        elif f == "price":
            if not isinstance(v, (int, float)) or isinstance(v, bool) or v < 0:
                return jsonify(error="price must be a non-negative number"), 400
            candidate[f] = float(v)
        elif f == "stock":
            if not isinstance(v, int) or isinstance(v, bool) or v < 0:
                return jsonify(error="stock must be a non-negative integer"), 400
            candidate[f] = v

    old = row_to_dict(row)
    changes = diff_fields(old, candidate)

    if changes:
        db.execute(
            "UPDATE products SET name = ?, price = ?, stock = ? WHERE id = ?",
            (candidate["name"], candidate["price"], candidate["stock"], entity_id),
        )
        write_audit("PUT" if full_replace else "PATCH", entity_id, changes)
        db.commit()

    updated = db.execute("SELECT * FROM products WHERE id = ?", (entity_id,)).fetchone()
    return jsonify(row_to_dict(updated)), 200


@app.put("/products/<int:product_id>")
def put_product(product_id: int):
    return _apply_update(product_id, request.get_json(silent=True), full_replace=True)


@app.patch("/products/<int:product_id>")
def patch_product(product_id: int):
    return _apply_update(product_id, request.get_json(silent=True), full_replace=False)


@app.delete("/products/<int:product_id>")
def delete_product(product_id: int):
    db = get_db()
    row = db.execute("SELECT * FROM products WHERE id = ?", (product_id,)).fetchone()
    if row is None:
        # Failed mutation: log nothing.
        return jsonify(error="product not found"), 404

    old = row_to_dict(row)
    db.execute("DELETE FROM products WHERE id = ?", (product_id,))
    write_audit(
        "DELETE",
        product_id,
        {f: {"old": old[f], "new": None} for f in ("name", "price", "stock")},
    )
    db.commit()
    return "", 204


@app.get("/products")
def list_products():
    rows = get_db().execute("SELECT * FROM products ORDER BY id").fetchall()
    return jsonify([row_to_dict(r) for r in rows])


@app.get("/products/<int:product_id>")
def get_product(product_id: int):
    row = get_db().execute("SELECT * FROM products WHERE id = ?", (product_id,)).fetchone()
    if row is None:
        return jsonify(error="product not found"), 404
    return jsonify(row_to_dict(row))


@app.get("/products/<int:product_id>/history")
def product_history(product_id: int):
    """Return the raw audit trail (oldest first) and a replay that reconstructs
    the current row by folding each diff onto the original (empty) state."""
    db = get_db()
    rows = db.execute(
        "SELECT ts, actor, action, diff FROM audit_log "
        "WHERE entity_id = ? ORDER BY id ASC",
        (product_id,),
    ).fetchall()

    trail = [
        {"ts": r["ts"], "actor": r["actor"], "action": r["action"], "diff": json.loads(r["diff"])}
        for r in rows
    ]

    # Replay oldest-first: start from the original (pre-creation) state and
    # apply every change in order. The result equals the live row (or shows
    # all-None fields if the product was deleted).
    state: dict = {}
    exists = False
    for entry in trail:
        for field, change in entry["diff"].items():
            state[field] = change["new"]
        if entry["action"] != "DELETE":
            exists = True
        else:
            exists = False

    return jsonify({"exists": exists, "current": state, "log": trail})


if __name__ == "__main__":
    init_db()
    app.run(debug=True, port=5001)

